input.command:
EXE=/workspace/dataset/test10_executable
echo "### final: exhaustive structural assertion over 300 varied runs"
bad=0
for i in $(seq 1 300); do
  n=$(( RANDOM % 8 + 1 ))
  b=""; for j in $(seq 1 $n); do v=$(( RANDOM % 200000 - 100000 )); b="${b:+$b,}$v"; done
  a=$(head -c $(( RANDOM % 6 + 1 )) /dev/urandom | tr -dc 'a-zA-Z0-9'); a="${a:-x}"
  $EXE --a "$a" --b="$b" >/tmp/f.out 2>/tmp/f.err; rc=$?
  [ $rc -ne 0 ] && { echo "  RC!=0: a=$a b=$b rc=$rc"; bad=$((bad+1)); continue; }
  [ -s /tmp/f.err ] && { echo "  STDERR: a=$a b=$b"; bad=$((bad+1)); }
  nl=$(tr -cd '\n' < /tmp/f.out | wc -c)
  [ "$nl" -ne 2 ] && { echo "  NEWLINES=$nl: a=$a b=$b"; bad=$((bad+1)); }
  tail -c 1 /tmp/f.out | od -An -c | grep -q '\\n' || { echo "  NO TRAILING NL: a=$a b=$b"; bad=$((bad+1)); }
  head -1 /tmp/f.out | grep -qE '^\[(0|[1-9]|[12][0-9]|3[01])(, (0|[1-9]|[12][0-9]|3[01])){5}\]$' || { echo "  BADLINE1: $(head -1 /tmp/f.out) a=$a b=$b"; bad=$((bad+1)); }
  [ "$(sed -n 2p /tmp/f.out)" = "True" ] || { echo "  LINE2!=True: $(sed -n 2p /tmp/f.out)"; bad=$((bad+1)); }
done
echo "violations=$bad / 300 runs"
